USE ecommerce_analytics;
SELECT SUM(o.Quantity*p.Selling_Price*(1-o.Discount)) Total_Revenue,SUM(o.Quantity*p.Cost_Price) Total_Cost,SUM(o.Quantity*p.Selling_Price*(1-o.Discount)-o.Quantity*p.Cost_Price-COALESCE(o.Shipping_Cost,0)) Total_Profit FROM Orders o JOIN Products p ON o.Product_ID=p.Product_ID WHERE LOWER(TRIM(o.Order_Status))<>'cancelled' AND o.Quantity>0;
SELECT YEAR(o.Order_Date) Year,MONTH(o.Order_Date) Month,SUM(o.Quantity*p.Selling_Price*(1-o.Discount)) Revenue FROM Orders o JOIN Products p ON o.Product_ID=p.Product_ID WHERE LOWER(TRIM(o.Order_Status))<>'cancelled' GROUP BY YEAR(o.Order_Date),MONTH(o.Order_Date) ORDER BY Year,Month;
SELECT p.Category,SUM(o.Quantity*p.Selling_Price*(1-o.Discount)) Revenue,SUM(o.Quantity*p.Selling_Price*(1-o.Discount)-o.Quantity*p.Cost_Price-COALESCE(o.Shipping_Cost,0)) Profit FROM Orders o JOIN Products p ON o.Product_ID=p.Product_ID WHERE LOWER(TRIM(o.Order_Status))<>'cancelled' GROUP BY p.Category ORDER BY Revenue DESC;
SELECT c.Region,SUM(o.Quantity*p.Selling_Price*(1-o.Discount)) Revenue,SUM(o.Quantity*p.Selling_Price*(1-o.Discount)-o.Quantity*p.Cost_Price-COALESCE(o.Shipping_Cost,0)) Profit FROM Orders o JOIN Products p ON o.Product_ID=p.Product_ID JOIN Customers c ON o.Customer_ID=c.Customer_ID WHERE LOWER(TRIM(o.Order_Status))<>'cancelled' GROUP BY c.Region ORDER BY Revenue DESC;
SELECT c.Customer_ID,c.Customer_Name,SUM(o.Quantity*p.Selling_Price*(1-o.Discount)) Revenue FROM Orders o JOIN Products p ON o.Product_ID=p.Product_ID JOIN Customers c ON o.Customer_ID=c.Customer_ID WHERE LOWER(TRIM(o.Order_Status))<>'cancelled' GROUP BY c.Customer_ID,c.Customer_Name ORDER BY Revenue DESC LIMIT 10;
SELECT p.Product_ID,p.Product_Name,SUM(o.Quantity*p.Selling_Price*(1-o.Discount)) Revenue,SUM(o.Quantity*p.Selling_Price*(1-o.Discount)-o.Quantity*p.Cost_Price-COALESCE(o.Shipping_Cost,0)) Profit FROM Orders o JOIN Products p ON o.Product_ID=p.Product_ID WHERE LOWER(TRIM(o.Order_Status))<>'cancelled' GROUP BY p.Product_ID,p.Product_Name HAVING Revenue>100000 ORDER BY Profit;
SELECT CASE WHEN o.Discount=0 THEN '0%' WHEN o.Discount<=.10 THEN '1-10%' WHEN o.Discount<=.20 THEN '11-20%' ELSE '21%+' END Discount_Band,SUM(o.Quantity*p.Selling_Price*(1-o.Discount)) Revenue,SUM(o.Quantity*p.Selling_Price*(1-o.Discount)-o.Quantity*p.Cost_Price-COALESCE(o.Shipping_Cost,0)) Profit FROM Orders o JOIN Products p ON o.Product_ID=p.Product_ID WHERE LOWER(TRIM(o.Order_Status))<>'cancelled' GROUP BY Discount_Band;
SELECT COUNT(DISTINCT o.Order_ID) Total_Orders,COUNT(DISTINCT r.Order_ID) Returned_Orders,ROUND(COUNT(DISTINCT r.Order_ID)/NULLIF(COUNT(DISTINCT o.Order_ID),0)*100,2) Return_Rate_Percent FROM Orders o LEFT JOIN Returns r ON o.Order_ID=r.Order_ID;
SELECT TRIM(Payment_Method) Payment_Method,COUNT(DISTINCT Order_ID) Orders FROM Orders GROUP BY TRIM(Payment_Method) ORDER BY Orders DESC;
SELECT c.Region,SUM(COALESCE(o.Shipping_Cost,0)) Shipping_Cost FROM Orders o JOIN Customers c ON o.Customer_ID=c.Customer_ID GROUP BY c.Region ORDER BY Shipping_Cost DESC;